def _mcq(eid, title, kind, items):
    if kind == "listening":
        items = [
            dict(script=script, q=q, options=opts, answer=ans, explain=ex)
            for script, q, opts, ans, ex in items
        ]
    elif kind == "reading" and items and len(items[0]) == 5:
        items = [
            dict(text=txt, q=q, options=opts, answer=ans, explain=ex)
            for txt, q, opts, ans, ex in items
        ]
    else:
        items = [
            dict(q=q, options=opts, answer=ans, explain=ex)
            for q, opts, ans, ex in items
        ]
    # Correct answers are deliberately spread across four positions. The hash
    # gives each quiz a stable, non-obvious order across exports and book builds.
    digest = lambda value: hashlib.sha256(value.encode("utf-8")).digest()
    slot_order = sorted(range(4), key=lambda slot: digest(f"{eid}:slot:{slot}"))
    balanced = []
    for item_index, item in enumerate(items):
        options = list(item["options"])
        answer = item["answer"]
        if len(options) != 4 or not isinstance(answer, int) or not 0 <= answer < 4:
            raise ValueError(f"{eid}: expected four choices and one valid answer")
        if len(set(options)) != 4:
            raise ValueError(f"{eid}: answer choices must be distinct")
        target = slot_order[item_index % len(slot_order)]
        distractors = [i for i in range(4) if i != answer]
        distractors.sort(key=lambda choice: digest(f"{eid}:q{item_index}:choice:{choice}"))
        order = distractors[:]
        order.insert(target, answer)
        balanced.append({**item, "options": [options[i] for i in order], "answer": target})
    return MCQ(eid, title, kind, "Choose the best answer. Use the explanation to check the evidence and the reasoning.", balanced)


def build_unit(index):
    u = UNITS[index - 1]
    n = index
    grammar_id = f"b2g{index:02d}"
    blocks = [
        H(f"{n}.1 Words: language for {u['title'].split(':')[0].lower()}"),
        P(f"Start with the situation, not a translation list. Learn {len(u['vocab'])} focus terms in five short sets. Read each example for meaning, listen once for the speaker's purpose, then retrieve the term with your notes closed. These are original course examples; any figures or notices in this unit are fictional."),
        *[
            WORDS(u["vocab"][start:start + 6], f"B2 unit {n}: core topic language — set {start // 6 + 1}")
            for start in range(0, len(u["vocab"]), 6)
        ],
        H(f"{n}.2 Phrases: reusable discourse moves"),
        P("These chunks help you organize a real response. Choose the one that matches your meaning, say it from memory, and replace the topic details with your own."),
        WORDS([(fr, "Link the words smoothly; stress the final syllable group.", en, "", "") for fr, en, _ in u["chunks"]], "Meaning, register and transfer"),
        H(f"{n}.3 Grammar: {u['grammar_title']}"),
        H3(u["grammar_title"]), P(u["grammar_body"]),
        TABLE(["Meaning", "Form", "Example (hear)", "English"], u["grammar_rows"], u["grammar_title"]),
        _mcq(f"{n}.3G", "Check the grammar choice", "reading", u["grammar_q"]),
        H(f"{n}.4 Dialogues: follow the meaning and respond"),
        P("Listen for the speakers' goals and how each response changes the exchange. Read once for meaning, then cover the English and summarize each person's position."),
    ]
    for title, setting, lines in u["dialogues"]:
        blocks.append(DIALOGUE(title, setting, lines))
    story = B2_STORIES.get(index)
    if story:
        blocks += [
            H(f"{n}.5 Story: {story['title']}"),
            P(story["intro"]),
            STORY(story["title"], story["title_en"], story["sentences"], story["notes"]),
            _mcq(f"{n}.5R", "Read the story closely", "reading", story["questions"]),
        ]
    blocks += [
        H(f"{n}.6 Listening: stance, evidence and detail"),
        P("Learning mode: listen for the gist first; then replay if needed and check the transcript through the examples. TCF-style items are marked separately in the final section and should be attempted once before feedback."),
        _mcq(f"{n}.6L", "Listen for the argument", "listening", u["listening"]),
        H(f"{n}.7 Reading: purpose, position and inference"),
        P("Read the question first, then locate the line or relationship that supports your answer. Separate what the text states from what you infer; a plausible outside fact is not evidence for the question. Some words are new by design: use context, word families and Marie's explanation for high-value gaps instead of translating every line."),
        _mcq(f"{n}.7R", "Read and find the evidence", "reading", u["reading"]),
        H(f"{n}.8 Writing: plan, draft, check and rewrite"),
        WRITE(f"{n}.8W", f"TCF Task {u['write']['kind']} practice", u["write"]["prompt"], u["write"]["model"], u["write"]["checklist"]),
        *[
            WRITE(f"{n}.8W{j}", f"TCF Task {extra['kind']} practice", extra["prompt"], extra["model"], extra["checklist"])
            for j, extra in enumerate(u.get("write_extra", []), 1)
        ],
        H(f"{n}.9 Speaking: answer, interact and transfer"),
        SPEAK(f"{n}.9S", "Goal-bound speaking practice", u["speak"]["prompt"], u["speak"]["model"], u["speak"]["tips"]),
        *[
            SPEAK(f"{n}.9S{j}", extra["title"], extra["prompt"], extra["model"], extra["tips"])
            for j, extra in enumerate(u.get("speak_extra", []), 1)
        ],
        H(f"{n}.10 TCF corner and mastery checkpoint"),
        P("These are original practice items, not official TCF questions. Check the current candidate information before booking a test. A course checkpoint is evidence for review, not a predicted score."),
        _mcq(f"{n}.10L", "TCF-style listening: one play", "listening", u["listening"][:2]),
        _mcq(f"{n}.10R", "TCF-style reading", "reading", u["reading"][:2]),
        _mcq(f"{n}.10C", "Cumulative checkpoint", "reading", u["checkpoint"]),
        H(f"Unit {n}: transfer check"),
        LIST(
            f"I can {u['can_do'][0].lower()}{u['can_do'][1:] if u['can_do'] else ''}",
            "I can explain the grammar choice by meaning, then use it in a new sentence without copying the example.",
            "I can listen and read for the main point, evidence and limitation rather than translating every word.",
            "I can complete the unit's speaking and writing task with notes closed, then revise one specific weakness.",
            "I can use the unit's language in a changed situation and identify what I still need to review.",
        ),
    ]
    if index == 1:
        diagnostic = [
            H("1.0 B2 readiness check: record a baseline before Unit 1"),
            P("B2 assumes a completed B1 pathway. Before learning the unit, complete one short task in each skill with no notes, translation app or model. Save the first attempts in your notes app. This is a personal baseline, not a placement decision or predicted exam score. If connected past narration, longer listening or spontaneous interaction is still difficult, finish the B1 pathway before relying on these B2 lessons."),
            _mcq("1.0L", "Baseline listening", "listening", B2_ENTRY_DIAGNOSTIC["listening"]),
            _mcq("1.0R", "Baseline reading", "reading", B2_ENTRY_DIAGNOSTIC["reading"]),
            WRITE("1.0W", "Baseline writing sample", B2_ENTRY_DIAGNOSTIC["write"]["prompt"], B2_ENTRY_DIAGNOSTIC["write"]["model"], B2_ENTRY_DIAGNOSTIC["write"]["checklist"]),
            SPEAK("1.0S", "Baseline speaking sample", B2_ENTRY_DIAGNOSTIC["speak"]["prompt"], B2_ENTRY_DIAGNOSTIC["speak"]["model"], B2_ENTRY_DIAGNOSTIC["speak"]["tips"]),
            *blocks,
        ]
        blocks = diagnostic
    ch = chapter(
        f"b2-u{n:02d}", f"B2 · Unit {n}", f"B2 · {u['title']}", badge=f"B2.{n}",
        can_do=u["can_do"], situation=u["situation"],
        canada=[
            "Scenarios are fictional Canadian adult contexts. They are language practice, not current legal, medical, financial, immigration or public-service instructions.",
            "Use clear, broadly intelligible French for production. Ask Marie to vary details and roles so the learner practises meaning, not a memorized script.",
            "For iPad split-screen study, record one useful contrast and one corrected personal sentence; close notes before retrieval and return after a delay.",
        ],
        blocks=blocks,
    )
    if story:
        ch["story_meta"] = {
            "id": story["id"], "minutes": 7, "summary": story["summary"],
            "keywords": story["keywords"],
        }
        ch["story_gloss"] = story["gloss"]
    return ch
